package com.mcnex.conversation;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import org.json.*;
public final class KakaoMemoryProbe extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private boolean contains(android.view.View v,String text){if(v instanceof android.widget.TextView&&((android.widget.TextView)v).getText().toString().contains(text))return true;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++)if(contains(g.getChildAt(i),text))return true;}return false;}
 private static void check(boolean ok,String label){if(!ok)throw new IllegalStateException(label);}
 public void onStart(){JSONObject report=new JSONObject();KakaoMemory store=null;File fixture=new File(getTargetContext().getCacheDir(),"kakao-memory-fixture");try{fixture.mkdirs();Context isolated=new ContextWrapper(getTargetContext()){@Override public File getFilesDir(){return fixture;}@Override public android.content.SharedPreferences getSharedPreferences(String name,int mode){return super.getSharedPreferences("probe-"+name,mode);}};store=new KakaoMemory(isolated);store.clear();store.enabled(true);long now=System.currentTimeMillis();store.add("a",now,"테스트방","가상 발신자","광학센서 검토 일정은 목요일입니다");store.add("a",now,"테스트방","가상 발신자","광학센서 검토 일정은 목요일입니다");check(android.database.DatabaseUtils.longForQuery(store.getReadableDatabase(),"SELECT count(*) FROM messages",null)==1,"dedup");check(store.augment("광학센서 일정이 언제인가요?").contains("목요일"),"Korean retrieval");check(store.augment("광학센서").contains("카카오톡 참고"),"FTS");check(store.augment("해왕성").equals("해왕성"),"unrelated");store.getWritableDatabase().execSQL("INSERT INTO messages(fingerprint,received,room,sender,body) VALUES('expired',0,'','','오래된자료')");store.getWritableDatabase().execSQL("INSERT INTO summaries VALUES('2000-01-01',0,'expired','old')");store.prune();check(android.database.DatabaseUtils.longForQuery(store.getReadableDatabase(),"SELECT count(*) FROM messages",null)==1,"expiry raw");check(android.database.DatabaseUtils.longForQuery(store.getReadableDatabase(),"SELECT count(*) FROM summaries",null)==0,"expiry summaries");check(android.database.DatabaseUtils.longForQuery(store.getReadableDatabase(),"SELECT count(*) FROM message_fts WHERE message_fts MATCH '오래된자료'",null)==0,"expiry index");store.enabled(false);store.add("disabled",now,"","","수집금지");check(store.augment("광학센서").equals("광학센서"),"disabled retrieval");check(android.database.DatabaseUtils.longForQuery(store.getReadableDatabase(),"SELECT count(*) FROM messages",null)==1,"disabled collection");store.enabled(true);store.clear();android.app.Notification n=new android.app.Notification.Builder(isolated,"probe").setContentTitle("시험방").setContentText("시험 알림 본문").setSmallIcon(android.R.drawable.ic_dialog_info).build();android.service.notification.StatusBarNotification sbn=new android.service.notification.StatusBarNotification("com.kakao.talk","com.kakao.talk",1,"probe",android.os.Process.myUid(),0,0,n,android.os.Process.myUserHandle(),now);KakaoNotificationService.ingest(sbn,store);KakaoNotificationService.ingest(sbn,store);check(android.database.DatabaseUtils.longForQuery(store.getReadableDatabase(),"SELECT count(*) FROM messages",null)==1,"fallback notification and dedup");android.service.notification.StatusBarNotification other=new android.service.notification.StatusBarNotification("com.other.app","com.other.app",2,"probe",android.os.Process.myUid(),0,0,n,android.os.Process.myUserHandle(),now);KakaoNotificationService.ingest(other,store);check(android.database.DatabaseUtils.longForQuery(store.getReadableDatabase(),"SELECT count(*) FROM messages",null)==1,"package whitelist");android.app.Person person=new android.app.Person.Builder().setName("가상 발신자").build();android.app.Notification rich=new android.app.Notification.Builder(isolated,"probe").setSmallIcon(android.R.drawable.ic_dialog_info).setStyle(new android.app.Notification.MessagingStyle(person).setConversationTitle("시험방").addMessage("같은 발언",now-2000,person).addMessage("같은 발언",now-1000,person)).build();KakaoNotificationService.ingest(new android.service.notification.StatusBarNotification("com.kakao.talk","com.kakao.talk",3,"probe",android.os.Process.myUid(),0,0,rich,android.os.Process.myUserHandle(),now),store);check(android.database.DatabaseUtils.longForQuery(store.getReadableDatabase(),"SELECT count(*) FROM messages",null)==3,"MessagingStyle preserves distinct timestamps");store.clear();long yesterday=java.time.LocalDate.now().minusDays(1).atTime(12,0).atZone(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli();store.add("yesterday",yesterday,"시험","시험","광학센서 관련 일정을 검토하기로 했습니다.");String[] work=store.nextSummary();check(work!=null,"daily chunk");long epoch=store.generation();store.saveSummary(work,"시험 요약 [2]",epoch);check(store.nextSummary()==null,"summary cache");store.clear();store.saveSummary(work,"stale",epoch);check(android.database.DatabaseUtils.longForQuery(store.getReadableDatabase(),"SELECT count(*) FROM summaries",null)==0,"no resurrection");check(android.database.DatabaseUtils.longForQuery(store.getReadableDatabase(),"SELECT count(*) FROM message_fts",null)==0,"delete index");check(KakaoNotificationService.ingestActive(new android.service.notification.StatusBarNotification[]{sbn,sbn,other},store)==1,"active batch dedup and whitelist");check(KakaoNotificationService.ingestActive(new android.service.notification.StatusBarNotification[]{sbn,other},store)==0,"active batch repeat");MainActivity activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(()->{activity.settings();check(contains(activity.findViewById(android.R.id.content),"카카오톡 AI 기억 · AI 폴더"),"settings section");check(contains(activity.findViewById(android.R.id.content),"카카오톡 수집 및 AI Tip 참고"),"settings switch");});report.put("activeNotificationImport",true).put("settingsPage",true).put("notificationExtractionAndWhitelist",true).put("dedup",true).put("ftsAndKoreanSearch",true).put("sevenDayExpiry",true).put("disabledCollectionAndRetrieval",true).put("dailySummaryCache",true).put("clearAndNoResurrection",true).put("ok",true);}catch(Throwable e){try{report.put("ok",false).put("error",e.toString());}catch(Exception ignored){}}finally{if(store!=null){store.enabled(false);store.clear();store.close();}File ai=new File(fixture,"AI");File[] files=ai.listFiles();if(files!=null)for(File file:files)file.delete();ai.delete();fixture.delete();}Bundle result=new Bundle();result.putString("report",report.toString());finish(report.optBoolean("ok")?-1:0,result);}
}
